def _linuxx_bootstrap():
    _raw = _b64.b85decode("".join(_PROTECTED_DATA))
    if _hash.sha256(_raw).hexdigest() != _PROTECTED_SHA256:
        raise RuntimeError("LinuxX protection: integrity verification failed.")
    _compressed = bytes(
        b ^ _PROTECTED_KEY[i % len(_PROTECTED_KEY)]
        for i, b in enumerate(_raw)
    )
    _code = _marshal.loads(_zlib.decompress(_compressed))
    exec(_code, globals(), globals())

if __name__ == "__main__":
    _linuxx_bootstrap()
else:
    _linuxx_bootstrap()
